/* Catalan Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jordi": "farmer, earthworker — Greek Georgios", "Montserrat": "serrated mountain — Catalan", "Josep": "God increases — Hebrew Yosef", "Anna": "grace — Hebrew Hannah", "Pere": "rock, stone — Greek petros", "Nuria": "A feminine name from the Pyrenean valley sanctuary.", "Puig": "A classic Catalan surname meaning hill.", "Ferrer": "A classic craft surname.", "Vidal": "A widespread surname.", "Serra": "A classic surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jordi';
console.log(lookup(q));

